import { useMemo, useState } from 'react';
import {
  JxBadge,
  JxButton,
  JxChip,
  JxEmptyState,
  JxPagination,
  JxProgressCircle,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'paused' | 'over';

interface Project {
  id: string;
  name: string;
  used: number;
  quota: number;
  status: ProjectStatus;
}

const STATUSES: Array<{ value: ProjectStatus; label: string; tone: 'success' | 'warning' | 'danger' }> = [
  { value: 'active', label: 'Активные', tone: 'success' },
  { value: 'paused', label: 'На паузе', tone: 'warning' },
  { value: 'over', label: 'Превышен расход', tone: 'danger' },
];

const PROJECTS: Project[] = [
  { id: 'p1', name: 'Контекстная библиотека', used: 420, quota: 1000, status: 'active' },
  { id: 'p2', name: 'Индексация документации', used: 980, quota: 1000, status: 'over' },
  { id: 'p3', name: 'Ночные прогоны оценок', used: 150, quota: 800, status: 'paused' },
  { id: 'p4', name: 'Панель наблюдаемости', used: 610, quota: 900, status: 'active' },
  { id: 'p5', name: 'Миграция хранилища заметок', used: 75, quota: 500, status: 'paused' },
  { id: 'p6', name: 'Экспорт отчётов в Obsidian', used: 1240, quota: 1000, status: 'over' },
  { id: 'p7', name: 'Сборка токенов оформления', used: 320, quota: 600, status: 'active' },
  { id: 'p8', name: 'Проверка доступности интерфейса', used: 210, quota: 700, status: 'active' },
  { id: 'p9', name: 'Архив прошлых экспериментов', used: 40, quota: 400, status: 'paused' },
  { id: 'p10', name: 'Пересчёт квот по командам', used: 1010, quota: 1000, status: 'over' },
  { id: 'p11', name: 'Правила набора и линтер', used: 480, quota: 900, status: 'active' },
];

const PAGE_SIZE = 5;

function ProjectSpendPanel() {
  const [statuses, setStatuses] = useState<ProjectStatus[]>(['active', 'paused', 'over']);
  const [page, setPage] = useState(1);

  const visible = useMemo(
    () => PROJECTS.filter((project) => statuses.includes(project.status)),
    [statuses],
  );

  const pageCount = Math.max(1, Math.ceil(visible.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);
  const rows = visible.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE);

  const toggleStatus = (value: ProjectStatus) => {
    setStatuses((prev) => (prev.includes(value) ? prev.filter((item) => item !== value) : [...prev, value]));
    setPage(1);
  };

  const resetFilters = () => {
    setStatuses(STATUSES.map((status) => status.value));
    setPage(1);
  };

  return (
    <section style={{ display: 'grid', gap: '20px', fontFamily: 'var(--jx-font-sans)', color: 'var(--jx-text)' }}>
      <div>
        <h2 style={{ margin: '0 0 4px', fontFamily: 'var(--jx-font-display)', fontSize: '20px' }}>
          Расход по проектам
        </h2>
        <p style={{ margin: 0, color: 'var(--jx-text-2)', fontSize: '14px' }}>
          Заполненность квоты за текущий месяц.
        </p>
      </div>

      <div
        role="group"
        aria-label="Фильтр по статусу"
        style={{ display: 'flex', flexWrap: 'wrap', gap: '8px', alignItems: 'center' }}
      >
        {STATUSES.map((status) => {
          const active = statuses.includes(status.value);
          return (
            <JxChip
              key={status.value}
              active={active}
              removable={active}
              onRemove={() => toggleStatus(status.value)}
              role="button"
              tabIndex={0}
              aria-pressed={active}
              onClick={() => toggleStatus(status.value)}
              onKeyDown={(event) => {
                if (event.key === 'Enter' || event.key === ' ') {
                  event.preventDefault();
                  toggleStatus(status.value);
                }
              }}
            >
              {status.label}
            </JxChip>
          );
        })}
      </div>

      {rows.length === 0 ? (
        <JxEmptyState
          title="Под фильтры ничего не подошло"
          message="Сняты все статусы или под выбранные условия нет проектов. Верните фильтры, чтобы увидеть список."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <ul style={{ display: 'grid', gap: '8px', listStyle: 'none', margin: 0, padding: 0 }}>
            {rows.map((project) => {
              const status = STATUSES.find((item) => item.value === project.status);
              const percent = Math.round((project.used / project.quota) * 100);
              return (
                <li
                  key={project.id}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: '16px',
                    padding: '12px 16px',
                    background: 'var(--jx-surface)',
                    border: '1px solid var(--jx-border)',
                    borderRadius: 'var(--jx-r)',
                  }}
                >
                  <JxProgressCircle value={percent} max={100} showValue aria-label={`Квота: ${percent} процентов`} />
                  <div style={{ display: 'grid', gap: '2px', minWidth: 0, flex: 1 }}>
                    <span
                      style={{
                        fontSize: '15px',
                        overflow: 'hidden',
                        textOverflow: 'ellipsis',
                        whiteSpace: 'nowrap',
                      }}
                      title={project.name}
                    >
                      {project.name}
                    </span>
                    <span style={{ fontSize: '13px', color: 'var(--jx-text-2)' }}>
                      {project.used} из {project.quota} единиц
                    </span>
                  </div>
                  {status ? <JxBadge tone={status.tone} dot>{status.label}</JxBadge> : null}
                </li>
              );
            })}
          </ul>

          {pageCount > 1 ? (
            <JxPagination total={pageCount} page={currentPage} onPageChange={setPage} aria-label="Страницы проектов" />
          ) : null}
        </>
      )}
    </section>
  );
}

export default ProjectSpendPanel;

